      "path": "src/quota.ts",
      "content": "import { readFile } from 'node:fs/promises'
import { existsSync } from 'node:fs'
import { join } from 'node:path'
import type { MembersFile, QuotaStatus } from './types.js'
import type { UsageStore } from './store.js'

const RELOAD_MS = 60_000

/**
 * Member budgets + threshold alerts + optional enforcement.
 *
 * Budgets live in <dataDir>/members.json ({ "members": [{ name, dailyCost,
 * monthlyCost, dailyTokens, monthlyTokens }] }) and hot-reload every minute,
 * so admins edit the file without restarting DSH.
 */
export class Quota {
  private members = new Map<string, { dailyCost?: number; monthlyCost?: number; dailyTokens?: number; monthlyTokens?: number }>()
  private lastLoad = 0
  private alerted = new Set<string>()
  private reloadTimer: ReturnType<typeof setInterval> | undefined

  constructor(
    private readonly dataDir: string,
    private readonly store: UsageStore,
    private readonly thresholds: readonly number[],
    private readonly webhook: string,
    private readonly onError?: (err: unknown) => void,
  ) {}

  start(): void {
    this.reloadTimer = setInterval(() => this.loadMembers().catch((e) => this.onError?.(e)), RELOAD_MS)
    this.reloadTimer.unref?.()
  }

  dispose(): void {
    if (this.reloadTimer) clearInterval(this.reloadTimer)
  }

  get membersPath(): string {
    return join(this.dataDir, 'members.json')
  }

  async loadMembers(): Promise<void> {
    this.lastLoad = Date.now()
    if (!existsSync(this.membersPath)) return
    try {
      const parsed: unknown = JSON.parse(await readFile(this.membersPath, 'utf8'))
      const file = parsed as MembersFile
      if (Array.isArray(file.members)) {
        this.members = new Map(file.members.map((m) => [m.name, m]))
      }
    } catch (err) {
      this.onError?.(err)
    }
  }

  private ensureFresh(): void {
    if (Date.now() - this.lastLoad > RELOAD_MS) void this.loadMembers()
  }

  /** All configured member names (budget file order). */
  memberNames(): string[] {
    this.ensureFresh()
    return [...this.members.keys()]
  }

  /** Budget lines for one member, or {} when unconfigured. */
  budgetsFor(user: string): { dailyCost?: number; monthlyCost?: number; dailyTokens?: number; monthlyTokens?: number } {
    this.ensureFresh()
    const b = this.members.get(user)
    if (!b) return {}
    return { dailyCost: b.dailyCost, monthlyCost: b.monthlyCost, dailyTokens: b.dailyTokens, monthlyTokens: b.monthlyTokens }
  }

  /**
   * Evaluate one metered call. Fires webhook alerts on newly crossed
   * thresholds (per member+threshold, once per day) and returns the status.
   */
  async evaluate(user: string): Promise<QuotaStatus> {
    this.ensureFresh()
    const budget = this.members.get(user)
    const totals = this.store.totalsFor(user)
    const status: QuotaStatus = { user, level: 0, exceeded: [], over: false }
    if (!budget) return status

